    writingMinutes: 28,
    sourceEdition:
      "钱理群、温儒敏、吴福辉《中国现代文学三十年》（修订本），北京大学出版社",
    sourceLocation: "第二编·第十二章·第二节“《家》的杰出成就”艺术分析部分",
