    score: 20,
    outlineAnswer: "1. 总定位：用小说散文建造特异的'湘西世界'\n2. 出身与血统：凤凰县、苗汉土家血液\n3. 行伍经验：少年目睹杀戮，形成审美品格\n4. '乡下人'自我认同与实际身份\n5. 独立的文化立场：左翼与海派之外\n6. 人性理想：'希腊小庙'供奉'人性'\n7. 抒情本质与美学中的神性\n8. 文学史意义：丰富30年代文学多样性",
    answer: "一、总定位。教材明确指出，沈从文的主要文学贡献，是用小说和散文建造了一个特异的'湘西世界'；这一世界以'湘西人'为主体来叙述、观照。湘西因有了沈从文，'以一个无比淳朴的、自由的、满溢了生命力的王国出现在世人面前'，而他本人即是湘西的魂魄所在。\n\n二、出身与血统。沈从文（1902—1988），原名沈岳焕，生于荒僻而风光如画、富有传奇性的湘西凤凰县，身上流着苗、汉、土家各族的血液。这带给他特殊的气质、多彩的幻想，以及少数民族受压历史积淀下来的沉忧隐痛，构成湘西世界深层的心理底色。\n\n三、行伍经验与审美品格。他少年时代熟读'社会这本大书'，十四岁高小毕业后入地方行伍，在芷江四个月看杀人一千，在怀化镇一年多看杀人七百。过早面对残酷与黑暗，反而使他在日后书写残酷时消除了炫耀猎奇的可能，形成追求美好人生与善良德性的品格；他又熟悉川湘鄂黔四省交界的土地、沅水流域及人民的哀乐生活样式、吊脚楼的淳朴乡俗民风，养成对民间世俗事物特殊敏感的审美情趣。\n\n四、'乡下人'的自我认同与实际身份。沈从文一生自命'乡下人'，《习作选集代序》说乡下人保守顽固、爱土地、有机警而不懂诡诈、认真到'傻头傻脑'。但教材强调，他实际并非原生态的乡下人，而是一个具有'乡下人'眼光的都市知识者，时时以这种眼光看待中国的'常'与'变'。\n\n五、独立的文化立场。他领悟宗法农村自然经济的近代解体过程，接受'五四'启蒙、了解西方文明，动用乡村性生活积存充当现代中国文化的批判者。他不从党派政治角度写农村凋敝与都市罪恶，也不从现代商业文化角度表现物质进步与道德颓下；处于左翼文学和海派文学之外，取地域的、民族的文化历史态度，由城乡对峙的整体结构批判现代文明进入中国初始阶段的全部丑陋处。\n\n六、人性理想与'希腊小庙'。沈从文完成湘西系列，合成乡村生命形式的美丽与城市生命形式的批判性结构，提出人与自然'和谐共存'、本于自然回归自然的哲学。'湘西'代表着优美、健康、自然而又不悖乎人性的人生形式；他自称'我只想造希腊小庙'，'这神庙供奉的是人性'。其美学中含有'神性'概念，'美''爱''神'三者一体，瞩目于'一种美和爱的新的宗教'，神性即最高的人性。\n\n七、抒情本质。教材指出沈从文关切俗世情趣、情绪记忆高度发达、善于把握生活细节，'时时刻刻为人生现象自然现象所神往倾心'，将生命形式与生活形式高度统一，'这就是抒情'；其未完稿《抽象的抒情》认为文字语言表现的'本质不过是一种抒情'。\n\n八、创作规模与文学史意义。他创作结集约八十多部，为现代作家中成书最多者；早期《蜜柑》《雨后及其他》《神巫之爱》等已见主题端倪，但城乡线索不够清晰、两性描写较浅、文字纯净度差，三十年代后成熟。教材总结：他的城乡对峙书写丰富了三十年代中国文学的多样、多元特征。书目序列包括小说集《龙朱》《旅店及其他》《石子船》《虎雏》《阿黑小史》《月下小景》《八骏图》等，中长篇《阿丽思中国游记》《边城》《长河》，散文《从文自传》《湘行散记》《湘西》，文论《烛虚》《云南看云集》等。",
    highScoreAnswer: "沈从文的主要文学贡献是以小说、散文建造特异的'湘西世界'，以'湘西人'为主体叙述观照。其创造条件有四：一是生于湘西凤凰县、身流苗汉土各族血液，带来特殊气质与少数民族受压历史的沉忧隐痛；二是十四岁入行伍、在芷江怀化目睹大量杀戮，使其写残酷而消除猎奇，反生出追求美好德性的品格，并熟悉沅水流域人民的哀乐生活；三是自命'乡下人'，实为具'乡下人'眼光的都市知识者，以此看待中国的'常'与'变'；四是不从党派政治或商业文化角度写作，处于左翼与海派之外，取地域的、民族的文化历史态度，由城乡对峙结构批判现代文明初始阶段的全部丑陋处。'湘西'代表优美、健康、自然而又不悖乎人性的人生形式，他自称'只想造希腊小庙'，'这神庙供奉的是人性'；其文学本质是'抒情'，美、爱、神一体，神性即最高的人性。这一创造丰富了三十年代中国文学的多样多元特征。",
    keywords: ["沈从文", "湘西世界", "乡下人", "凤凰县", "苗汉土家血统", "行伍经验", "希腊小庙", "人性", "抒情", "抽象的抒情", "神性", "城乡对峙", "京派", "文化批判", "优美健康自然", "大公报文艺副刊"],
    points: ["主要贡献：用小说、散文建造特异的'湘西世界'", "生于湘西凤凰县，身有苗、汉、土家各族血液", "14岁入行伍，芷江看杀人一千、怀化看杀人七百", "写残酷愚昧时消除炫耀猎奇，追求美好人生与善良德性", "自命'乡下人'，实为具'乡下人'眼光的都市知识者", "不从党派政治或商业文化角度写作，取地域的民族的文化历史态度", "由城乡对峙整体结构批判现代文明初始阶段的丑陋处", "'我只想造希腊小庙'，'这神庙供奉的是人性'", "文学本质是'抒情'，生命形式与生活形式高度统一", "美、爱、神三者一体，神性即最高的人性", "丰富了三十年代中国文学的多样、多元特征", "创作结集约80多部，现代作家中成书最多"],
    examples: ["凤凰县出身与苗汉土家血统", "芷江、怀化看杀人的行伍经历", "1923年只身赴京自学写作", "以'休芸芸'笔名在《晨报副刊》《新月》等发表作品", "执编天津《大公报》文艺副刊，成为京派组织者", "《习作选集代序》'我实在是个乡下人'自述", "'希腊小庙供奉人性'自述", "未完稿《抽象的抒情》论文字本质是抒情", "早期小说集《蜜柑》《雨后及其他》《神巫之爱》", "少数民族情爱故事系列《龙朱》《媚金·豹子·与那羊》《月下小景》", "中长篇《边城》《长河》，散文《湘行散记》《湘西》"],
    estimatedWords: 1267,
    writingMinutes: 30,
    sourceEdition: "钱理群、温儒敏、吴福辉《中国现代文学三十年》（修订本），北京大学出版社",
