      "《淘金记》围绕筲箕背金矿开采写白酱丹、林么长子、何寡妇三股势力的内讧，进入不露声色的客观浓缩描写境界",
      "延安之行为沙汀小说增添光明因素，1944年学习《讲话》后创作思想变化，《还乡记》首塑走向集体斗争的贫农冯大生",
      "短篇集《呼嚎》《医生》揭露征兵、征粮、通货膨胀、镇压学生运动等丑行，《范老老师》出现争民主反内战新主题",
