      "艾芜抗战中消退《南行记》的浪漫风格，由《秋收》《纺车复活的时候》的光明书写转向暴露国统区农村的黑暗",
      "《丰饶的原野》以邵安娃、刘老九、赵长生三个农民形象解剖民族性格，探索以农立国的祖国命运",
