    sourceEdition: "钱理群、温儒敏、吴福辉《中国现代文学三十年》（修订本），北京大学出版社",
    sourceLocation: "第三编·第二十四章·第一节“雅俗对立的渐趋消解”与第二节“各类型通俗小说的‘现代化’”相关段落",
