  sourceEdition: "钱理群、温儒敏、吴福辉《中国现代文学三十年》（修订本），北京大学出版社",
  sourceLocation: "第三编·第二十七章·第三节“小品散文的多样风致”（梁实秋、张爱玲部分）",
