    keywords: ["李健吾","人物心理","喜剧艺术","性格矛盾","戏剧冲突","法国戏剧影响","《上海屋檐下》","《这不过是春天》","《梁充达》","《以身作则》","《一个女人和一条狗》","《武则天》","《民族危机与国防戏剧》","《生活知识》","《洪深与《农村三部曲>》","《光明》","《<近代戏剧选>序》","《戏剧大众化之实验》","《戏剧运动之今后》","《戏剧》","《大公报》","《人·演员·剧团》"],
    points: ["一、纯，又保持了生活本身的复杂性与丰富性。他巧妙地处理了共性与个性的关系：对每一家命运的揭示，每一个人物性格的刻画，都抓住其主要特征，加以准确、传神的勾勒，做到了用笔的极端简洁与鲜明，留下了大量的艺术空白让观众去想象、补充；同时又赋予“黄梅天气”以多层的象征意义，让五户人家各有个性的十多个人物统一在……","二、人道主义并没有使夏衍泯灭是非善恶界限，他的人道主义是与民主主义立场结合在一起的；这种人道主义精神使夏衍更关注于大时代中人的命运，特别是人的心灵、微妙的精神世界，使他的作品充满了人情味，产生了类似契诃夫含泪的微笑的艺术风格，构成了夏衍剧作的一个鲜明特色与优点。这一时期在剧坛上产生过较大影响而创作倾……","三、这一时期所创作的多幕剧《这不过是春天》可以说是他的代表作。从剧本表面情节看来，这是一出追捕革命者的革命题材的戏剧。但是实际上戏剧中的主人公不是革命者，而是警察厅长夫人。再和似水流年的矛盾，强烈的虚荣心和隐蔽的自卑感的矛盾”。其他人也同样如此：秘书为保住自己的职业而斗争，侦探利用夫人与旧情人的矛盾……","四、另一个颇有影响的多幕剧《梁充达》，是一个以农村生活为题材的剧本，也是作者创作中少有的悲剧。作者的兴趣仍然集中在对于主要人物梁允达内心矛盾的探讨，并渲染“处处是陷阱与罪恶”的时代感受，全剧给人一种沉闷甚至神秘的感觉。李健吾在1936年还写了反映农村生活的喜剧《以身作则》，讽刺封建礼教，有点类似旧戏……","五、同一时期袁牧之的戏剧与李健吾的风格有些近似。他的剧作并不完全脱离现实，但作者作剧的目的似乎在“为戏而戏”，很难说有什么社会意义，艺术上他的剧则有可取之处。例如1933年发表的独幕剧《一个女人和一条狗》，全剧只有两个角色，但很有戏剧性，作者利用人们的心理制作悬念，对话玲珑机智，并没有长篇大论，又穿……","六、宋之的的《武则天》是一部着重心理分析的历史剧，作者说他所要集中描写的是“在传统的封建社会下，也就是男性中心的社会下，一-个女性的反抗和挣扎”21）。作者在刻画女主人公的变态心理与行为时，所流露出的同情，在批评家茅盾看来，就是“迎和了小市民的趣味\"22”。注释【1]周钢鸣：《民族危机与国防戏剧》.……","七、【8][9][10][11】熊佛西：《戏剧大众化之实验》，南京：正中书局，1937年版，8页、14页、17页、20页、105一106页、90页。【12]欧阳予倩：《戏剧运动之今后》，载《戏剧》1卷4期，1929年11月15日出版。（14）据1937年1月24日《大公报》报道。[16】夏衍：《人·……","八、【18]于伶：《战斗的一生》，载《人民戏剧》8期，1982年8月出版。（19）张庚：《1936年的戏剧》，载《光明》2卷2期.1936年12月25日出版。20）见夏衍：《（上海屋檐下>后记》、《谈（上海屋檐下>的创作》，《夏衍剧作集》（一），北京：中国戏剧出版社.1984年版，257页、360一……"],
    examples: ["《这不过是春天》：教材本章用于说明本题的具体作家、作品或文学现象。","《梁允达》：教材本章用于说明本题的具体作家、作品或文学现象。","《新学究》：教材本章用于说明本题的具体作家、作品或文学现象。","《十三年》：教材本章用于说明本题的具体作家、作品或文学现象。","《以身作则》：教材本章用于说明本题的具体作家、作品或文学现象。","《青春》：教材本章用于说明本题的具体作家、作品或文学现象。","《贩马记》：教材本章用于说明本题的具体作家、作品或文学现象。","《金小玉》：教材本章用于说明本题的具体作家、作品或文学现象。","《上海屋檐下》：教材本章用于说明本题的具体作家、作品或文学现象。","《梁充达》：教材本章用于说明本题的具体作家、作品或文学现象。","《一个女人和一条狗》：教材本章用于说明本题的具体作家、作品或文学现象。","《武则天》：教材本章用于说明本题的具体作家、作品或文学现象。"],
