    examples: ["《在延安文艺座谈会上的讲话》：教材本章用于说明本题的具体作家、作品或文学现象。","文艺为工农兵服务：教材本章用于说明本题的具体作家、作品或文学现象。","思想感情改造：教材本章用于说明本题的具体作家、作品或文学现象。","普及与提高：教材本章用于说明本题的具体作家、作品或文学现象。","政治标准与艺术标准：教材本章用于说明本题的具体作家、作品或文学现象。","人民生活源泉：教材本章用于说明本题的具体作家、作品或文学现象。","批评与歌颂：教材本章用于说明本题的具体作家、作品或文学现象。","民族形式讨论：教材本章用于说明本题的具体作家、作品或文学现象。","《讲话》：教材本章用于说明本题的具体作家、作品或文学现象。","《新民主主义论》：教材本章用于说明本题的具体作家、作品或文学现象。"],
